# PATCH_APRIL_2026_V2
# Koreksi hasil ekstraksi workbook BID OPS April 2026.
# III.A rows 21-27 = level risiko.
# III.B AE21:AE27 = progress 25%,25%,25%,25%,25%,25%,100%.

_APRIL_LEVELS = {
    1: "Moderate",
    2: "Moderate To High",
    3: "Moderate",
    4: "Moderate To High",
    5: "Low To Moderate",
    6: "Low To Moderate",
    7: "Moderate",
}

_APRIL_PROGRESS = {
    1: 0.25,
    2: 0.25,
    3: 0.25,
    4: 0.25,
    5: 0.25,
    6: 0.25,
    7: 1.00,
}

for _block in SOURCE:
    if _block.get("month") == 4:
        for _no in range(1, 8):
            _block["items"][_no]["level_risiko"] = _APRIL_LEVELS[_no]
            _block["items"][_no]["progress"] = _APRIL_PROGRESS[_no]


def norm(value):
    text = str(value or "").lower()
    text = re.sub(r"[^a-z0-9]+", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def dec(value):
    if value in (None, "", "-", "#N/A", "#REF!", "#DIV/0!"):
        return None
    if isinstance(value, bool):
        return None
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return None


def pct(value):
    d = dec(value)
    if d is None:
        return None
    if Decimal("-1") <= d <= Decimal("1"):
        return d * Decimal("100")
    return d


def numeric_only(value):
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float, Decimal)):
        return dec(value)
    return None


def int_or_none(value):
    d = dec(value)
    return int(d) if d is not None else None


def scale(model, value):
    n = int_or_none(value)
    if n is None:
        return None
    return model.objects.filter(urutan=n).first()


def risk_type(value):
    t = norm(value)
    if "kuantitatif" in t:
        return "kuantitatif"
    if "kualitatif" in t:
        return "kualitatif"
    return None


def treatment_status(value):
    t = norm(value)
    if "discontinue" in t:
        return "discontinue"
    if "continue" in t:
        return "continue"
    return None


def get_prepared_by():
    User = get_user_model()
    return (
        User.objects.filter(username="armeizir").first()
        or User.objects.filter(is_superuser=True).order_by("id").first()
        or User.objects.order_by("id").first()
    )


def get_profile():
    qs = ReAssessmentSummary.objects.filter(tahun=YEAR)
    exact = qs.filter(judul__iexact="Profil Risk BidOPS").first()
    if exact:
        return exact
    candidates = [x for x in qs if "bidops" in norm(x.judul).replace(" ", "")]
    if len(candidates) == 1:
        return candidates[0]
    # fallback historical ID only if title/year still match
    by_id = qs.filter(pk=9).first()
    if by_id and "ops" in norm(by_id.judul):
        return by_id
    raise RuntimeError(
        "Profil Risiko BID OPS 2026 tidak dapat ditentukan secara unik. "
        f"Candidates={[(x.id, x.judul) for x in qs if 'ops' in norm(x.judul)]}"
    )


def get_period(tahun_buku, month):
    _, last_day = calendar.monthrange(YEAR, month)
    return PeriodeLaporan.objects.get_or_create(
        tahun_buku=tahun_buku,
        kode_periode=f"{YEAR}-{month:02d}",
        defaults={
            "nama_periode": f"{MONTH_NAMES[month]} {YEAR}",
            "jenis_periode": "bulanan",
            "tanggal_mulai": f"{YEAR}-{month:02d}-01",
            "tanggal_selesai": f"{YEAR}-{month:02d}-{last_day:02d}",
        },
    )[0]


def source_item(month, no):
    block = next(x for x in SOURCE if x["month"] == month)
    return block["items"][no]


def profile_map(profile):
    return {x.no_risiko: x for x in ReAssessmentItem.objects.filter(summary=profile).order_by("no_risiko", "id")}


def resolve_bpp_km_item(profile):
    qs = ItemKontrakManajemen.objects.filter(kontrak=profile.kontrak_manajemen)
    matches = [x for x in qs if "bpp" in norm(x.indikator_kinerja_kunci)]
    if len(matches) == 1:
        return matches[0]
    # Source legacy profile maps this risk to A.2/BPP; use risk-1 BPP item only if explicit.
    r1 = ReAssessmentItem.objects.filter(summary=profile, no_risiko=1).select_related("km_item").first()
    if r1 and r1.km_item and "bpp" in norm(r1.km_item.indikator_kinerja_kunci):
        return r1.km_item
    raise RuntimeError(
        "Tidak dapat menentukan Item KM BPP untuk Risiko 7. "
        f"KM={profile.kontrak_manajemen_id}, candidates={[(x.id, x.indikator_kinerja_kunci) for x in matches]}"
    )


def create_risk7(profile):
    existing = ReAssessmentItem.objects.filter(summary=profile, no_risiko=7).first()
    if existing:
        return existing, False

    src = source_item(7, 7)
    ref_energy = ReAssessmentItem.objects.filter(summary=profile, no_risiko=3).first()
    km_item = resolve_bpp_km_item(profile)
    timeline = src.get("timeline") or [None] * 12

    kwargs = dict(
        summary=profile,
        no_item=7,
        no_risiko=7,
        unit_bisnis=profile.unit_bisnis,
        km_item=km_item,
        peristiwa_risiko=src.get("event") or "Penggunaan gas non HGBT meningkat",
        deskripsi_peristiwa_risiko=src.get("deskripsi") or src.get("event") or "",
        no_penyebab_risiko=str(src.get("no_penyebab") or "")[:10] or None,
        penyebab_risiko=src.get("penyebab"),
        key_risk_indicators=src.get("kri"),
        unit_satuan_kri=str(src.get("unit_kri") or "")[:100] or None,
        threshold_aman=str(src.get("threshold_aman") or "")[:100] or None,
        threshold_hati_hati=str(src.get("threshold_hati_hati") or "")[:100] or None,
        threshold_bahaya=str(src.get("threshold_bahaya") or "")[:100] or None,
        rencana_perlakuan_risiko=src.get("rencana"),
        output_perlakuan_risiko=src.get("output"),
        biaya_perlakuan_risiko=dec(src.get("anggaran")),
        pic=str(src.get("pic") or "")[:255] or None,
    )
    for i in range(12):
        kwargs[f"timeline_{i+1}"] = 1 if i < len(timeline) and dec(timeline[i]) not in (None, Decimal("0")) else 0

    # Master-classification reference only where source and existing energy-primary risk align.
    if ref_energy:
        kwargs.update(
            sasaran_kbumn=ref_energy.sasaran_kbumn,
            kategori_risiko=ref_energy.kategori_risiko,
            taksonomi_t3=ref_energy.taksonomi_t3,
        )

    return ReAssessmentItem.objects.create(**kwargs), True


def change_type(value):
    t = norm(value)
    if "penambahan" in t and "risiko" in t:
        return MonthlyRiskReportChange.CHANGE_TYPE_ADD_ITEM
    if "pengurangan" in t and "risiko" in t:
        return MonthlyRiskReportChange.CHANGE_TYPE_REMOVE_ITEM
    if "strategi" in t:
        return MonthlyRiskReportChange.CHANGE_TYPE_STRATEGY
    if "profil" in t:
        return MonthlyRiskReportChange.CHANGE_TYPE_PROFILE
    return None


def import_changes(report, rows):
    MonthlyRiskReportChange.objects.filter(report=report).delete()
    count = 0
    for row in rows:
        typ = change_type(row.get("jenis"))
        if not typ:
            continue
        MonthlyRiskReportChange.objects.create(
            report=report,
            jenis_perubahan=typ,
            peristiwa_risiko_terdampak=row.get("peristiwa"),
            penjelasan=row.get("penjelasan"),
        )
        count += 1
    return count


def source_choice(value, yes="ya", no="tidak"):
    t = norm(value)
    if "ya" in t:
        return yes
    if "tidak" in t:
        return no
    return None


def source_external_internal(value):
    t = norm(value)
    if "eksternal" in t or "external" in t:
        return "external"
    if "internal" in t:
        return "internal"
    return None


def import_losses(report, rows):
    MonthlyRiskReportLossEvent.objects.filter(report=report).delete()
    count = 0
    for row in rows:
        g = lambda c: row.get(str(c))
        MonthlyRiskReportLossEvent.objects.create(
            report=report,
            nama_kejadian=g(2),
            identifikasi_kejadian=g(3),
            kategori_kejadian=g(4),
            sumber_penyebab_kejadian=source_external_internal(g(5)),
            penyebab_kejadian=g(6),
            penanganan_saat_kejadian=g(7),
            deskripsi_kejadian_risk_event=g(8),
            kategori_risiko_bumn=g(9),
            kategori_risiko_t2_t3_kbumn=g(10),
            penjelasan_kerugian=g(11),
            nilai_kerugian=dec(g(12)),
            kejadian_berulang=source_choice(g(13)),
            frekuensi_kejadian=g(14),
            mitigasi_direncanakan=g(15),
            realisasi_mitigasi=g(16),
            perbaikan_mendatang=g(17),
            pihak_terkait=g(18),
            status_asuransi=source_choice(g(19)),
            nilai_premi=dec(g(20)),
            nilai_klaim=dec(g(21)),
        )
        count += 1
    return count


def apply_item(report, risk_event, src):
    obj, created = MonthlyRiskReportItem.objects.get_or_create(report=report, risk_event=risk_event)
    obj.km_item = risk_event.km_item
    obj.jenis_risiko = risk_type(src.get("jenis_risiko"))
    obj.realisasi_asumsi_dampak = src.get("asumsi")
    obj.realisasi_nilai_dampak = dec(src.get("nilai_dampak"))
    obj.realisasi_skala_dampak = scale(MasterSkalaDampak, src.get("skala_dampak"))
    prob = pct(src.get("nilai_probabilitas"))
    obj.realisasi_nilai_probabilitas = prob
    obj.realisasi_skala_probabilitas = scale(MasterSkalaProbabilitas, src.get("skala_probabilitas"))
    obj.realisasi_eksposur = dec(src.get("eksposur"))
    obj.realisasi_skor_risiko = int_or_none(src.get("skor_risiko"))
    obj.realisasi_level_risiko = src.get("level_risiko")

    obj.realisasi_rencana_perlakuan = src.get("realisasi_rencana")
    obj.realisasi_output_perlakuan = src.get("realisasi_output")
    obj.realisasi_biaya_perlakuan = dec(src.get("realisasi_biaya"))
    obj.persentase_serapan_biaya = pct(src.get("serapan_biaya"))
    obj.realisasi_pic = str(src.get("pic") or "")[:255] or None
    obj.status_rencana_perlakuan = treatment_status(src.get("status"))
    obj.penjelasan_status_rencana = src.get("penjelasan_status")
    obj.progress_pelaksanaan_percent = pct(src.get("progress"))
    obj.realisasi_threshold_kri = (
        str(src.get("realisasi_threshold"))[:255]
        if src.get("realisasi_threshold") not in (None, "")
        else None
    )
    obj.realisasi_threshold_kri_skor = (
        str(src.get("realisasi_threshold_skor"))[:100]
        if src.get("realisasi_threshold_skor") not in (None, "")
        else None
    )
    obj.realisasi_nilai_kri = numeric_only(src.get("realisasi_threshold_skor"))
    obj.save()
    return obj, created


def audit():
    profile = get_profile()
    pmap = profile_map(profile)
    print("SOURCE AUDIT")
    for block in SOURCE:
        print(
            f"  {MONTH_NAMES[block['month']]}: risks={len(block['items'])}, "
            f"III.D={len(block['changes'])}, III.E={len(block['losses'])}, "
            f"III.A block={block['a_start']}, III.B KRI col={block['kri_col']}"
        )
    print("  source risk numbers: 1, 2, 3, 4, 5, 6, 7")

    print("BASELINE")
    print(
        f"  profile: id={profile.id}, judul={profile.judul!r}, status={profile.status}, "
        f"KM={profile.kontrak_manajemen_id}, existing risks={len(pmap)}"
    )
    for no in range(1, 8):
        if no in pmap:
            print(f"    risk {no}: FOUND id={pmap[no].id} {pmap[no].peristiwa_risiko}")
        else:
            print(f"    risk {no}: MISSING")
    if 7 not in pmap:
        km_item = resolve_bpp_km_item(profile)
        print(
            "  risk 7 source action: WILL CREATE on --apply; "
            f"KM item={km_item.id} {km_item.indikator_kinerja_kunci!r}"
        )

    tahun = TahunBuku.objects.filter(tahun=YEAR).first()
    if tahun:
        for month in range(3, 8):
            period = PeriodeLaporan.objects.filter(tahun_buku=tahun, kode_periode=f"{YEAR}-{month:02d}").first()
            report = MonthlyRiskReport.objects.filter(
                reassessment=profile, periode=period, versi=1
            ).first() if period else None
            if report:
                print(
                    f"  {MONTH_NAMES[month]} report: FOUND id={report.id}, "
                    f"kode={report.kode}, status={report.status}, items={report.items.count()}"
                )
            else:
                print(f"  {MONTH_NAMES[month]} report: MISSING -> will create")
    return profile


def run(apply=False):
    profile = audit()
    if not apply:
        print("MODE: AUDIT SAJA")
        print("Tidak ada data diubah. Jalankan kembali dengan --apply setelah audit output diperiksa.")
        return

    prepared_by = get_prepared_by()
    if not prepared_by:
        raise RuntimeError("Tidak ada user yang dapat dipakai sebagai prepared_by.")

    with transaction.atomic():
        pmap = profile_map(profile)
        risk7_created = False
        if 7 not in pmap:
            _, risk7_created = create_risk7(profile)
            pmap = profile_map(profile)

        missing = [n for n in range(1, 8) if n not in pmap]
        if missing:
            raise RuntimeError(f"Risk profile masih missing: {missing}")

        tahun_buku, _ = TahunBuku.objects.get_or_create(tahun=YEAR, defaults={"aktif": True})
        summaries = []
        for block in SOURCE:
            month = block["month"]
            period = get_period(tahun_buku, month)
            report, created = MonthlyRiskReport.objects.get_or_create(
                reassessment=profile,
                periode=period,
                versi=1,
                defaults={
                    "kode": f"MRR-OPS-{YEAR}-{month:02d}",
                    "tahun_buku": tahun_buku,
                    "status": "draft",
                    "prepared_by": prepared_by,
                    "kontrak_manajemen": profile.kontrak_manajemen,
                },
            )
            changed = []
            if not report.kode:
                report.kode = f"MRR-OPS-{YEAR}-{month:02d}"; changed.append("kode")
            if report.tahun_buku_id != tahun_buku.id:
                report.tahun_buku = tahun_buku; changed.append("tahun_buku")
            if not report.prepared_by_id:
                report.prepared_by = prepared_by; changed.append("prepared_by")
            if not report.kontrak_manajemen_id:
                report.kontrak_manajemen = profile.kontrak_manajemen; changed.append("kontrak_manajemen")
            if changed:
                report.save(update_fields=changed + ["updated_at"])

            created_items = 0
            for no in range(1, 8):
                _, item_created = apply_item(report, pmap[no], block["items"][no])
                created_items += int(item_created)

            d_count = import_changes(report, block["changes"])
            e_count = import_losses(report, block["losses"])

            report.total_risiko = report.items.count()
            report.total_high = report.items.filter(realisasi_level_risiko__icontains="high").count()
            report.total_mitigasi_terlambat = report.items.filter(mitigation_status="delayed").count()
            report.total_selesai = report.items.filter(status_rencana_perlakuan="discontinue").count()
            report.save(update_fields=[
                "total_risiko", "total_high", "total_mitigasi_terlambat",
                "total_selesai", "updated_at"
            ])
            summaries.append((month, report, created, created_items, d_count, e_count))

    print("MODE: APPLY")
    print("APPLY OK")
    print(f"  profile={profile.id} {profile.judul}; risk7_created={risk7_created}; risks={len(profile_map(profile))}")
    for month, report, created, created_items, d_count, e_count in summaries:
        print(
            f"  {MONTH_NAMES[month]}: report id={report.id}, kode={report.kode}, "
            f"created={created}, items={report.items.count()}, new_items={created_items}, "
            f"III.D={d_count}, III.E={e_count}, status={report.status}"
        )
        for no in range(1, 8):
            item = report.items.get(risk_event__no_risiko=no)
            print(
                f"    risk {no}: item={item.id}; impact={item.realisasi_nilai_dampak}; "
                f"prob={item.realisasi_nilai_probabilitas}; score={item.realisasi_skor_risiko}; "
                f"level={item.realisasi_level_risiko!r}; progress={item.progress_pelaksanaan_percent}; "
                f"KRI={item.realisasi_threshold_kri!r} / {item.realisasi_threshold_kri_skor!r}"
            )


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--apply", action="store_true", help="Commit perubahan ke database.")
    args = parser.parse_args()
    run(apply=args.apply)
